import { expect, expectStatus, test } from "../../fixtures";

test("approving the replacement W-9 approves a vendor whose other documents were already approved", { tag: "@LIF-06" }, async ({ factory, apiAs }) => {
  // Arrange: a submitted vendor, with insurance and contract approved and the W-9 sent back.
  const { vendor, extractions } = await factory.vendorInReview();
  const reviewer = await apiAs("reviewer");
  const member = await apiAs("member");

  expectStatus(
    await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  expectStatus(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "Please replace the W-9" },
    }),
    200,
  );

  // The member uploads a replacement W-9, waits for its extraction, and resubmits.
  const replacement = await factory.upload(vendor.id, "w9");
  await expect
    .poll(
      async () => {
        const doc = await expectStatus<{ status: string }>(await member.get(`/api/documents/${replacement.id}`), 200);
        return doc.status;
      },
      { message: "replacement W-9 extraction finishes", timeout: 30_000 },
    )
    .toBe("extracted");
  expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

  const pending = await factory.extraction(replacement.id, "reviewer");
  expect(pending.status, "replacement W-9 awaits review").toBe("pending_review");

  // Act: the reviewer approves the replacement W-9 extraction.
  const decided = await expectStatus<{ status: string }>(
    await reviewer.post(`/api/extractions/${pending.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  expect(decided.status).toBe("approved");

  // Assert: the stored vendor status and audit trail, re-read through the API.
  await expect
    .poll(
      async () => {
        const stored = await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
        return stored.status;
      },
      { message: "vendor becomes approved", timeout: 15_000 },
    )
    .toBe("approved");

  const trail = await expectStatus<{ items: { action: string }[] }>(
    await reviewer.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  expect(trail.items.map((e) => e.action)).toContain("vendor.approved");
});
